import hashlib, math, random

class Bloom:
    """Bloom filter a m bit con k funzioni hash ricavate da SHA-256 (sale = indice)."""
    def __init__(self, m, k):
        self.m, self.k, self.bits = m, k, 0

    def _positions(self, item: bytes):
        for i in range(self.k):
            d = hashlib.sha256(bytes([i]) + item).digest()
            yield int.from_bytes(d[:4], "big") % self.m

    def add(self, item: bytes):
        for p in self._positions(item):
            self.bits |= 1 << p

    def might_contain(self, item: bytes) -> bool:
        return all(self.bits >> p & 1 for p in self._positions(item))

    def __or__(self, other):          # unione = OR bit a bit (come il logsBloom del blocco)
        b = Bloom(self.m, self.k); b.bits = self.bits | other.bits; return b

def fp_teorico(m, k, n):
    return (1 - math.exp(-k * n / m)) ** k

random.seed(1)
m, k = 2048, 3                         # parametri del logsBloom di Ethereum
for n in (10, 50, 200):
    bf = Bloom(m, k)
    for i in range(n):
        bf.add(b"log-%d" % i)
    assert all(bf.might_contain(b"log-%d" % i) for i in range(n))   # nessun falso negativo
    trials = 20000
    fp = sum(bf.might_contain(b"altro-%d" % j) for j in range(trials)) / trials
    print(f"n={n:3d}  bit a 1={bin(bf.bits).count('1'):4d}  FP misurato={fp:.5f}  FP teorico={fp_teorico(m, k, n):.5f}")

# due receipt e il bloom del blocco
r1, r2 = Bloom(m, k), Bloom(m, k)
r1.add(b"Transfer"); r2.add(b"Deposit")
blocco = r1 | r2
print("blocco contiene Deposit?", blocco.might_contain(b"Deposit"), "| r1 contiene Deposit?", r1.might_contain(b"Deposit"))

